<?php
declare(strict_types=1);
namespace App\Services;
use PDO;
final class ProjectConnectionRepository { public function __construct(private readonly PDO $db){}public function connectionForProject(int $projectId):?array{$s=$this->db->prepare('SELECT pc.*,u.name attached_by_name FROM project_connections pc LEFT JOIN users u ON u.id=pc.attached_by_user_id WHERE pc.project_id=? LIMIT 1');$s->execute([$projectId]);return $s->fetch()?:null;}public function connectionByInstance(string $instance):?array{$s=$this->db->prepare('SELECT * FROM project_connections WHERE module_instance_id=? LIMIT 1');$s->execute([$instance]);return $s->fetch()?:null;}public function projectByCode(string $code):?array{$s=$this->db->prepare('SELECT * FROM projects WHERE code=? AND deleted_at IS NULL LIMIT 1');$s->execute([$code]);return $s->fetch()?:null;}public function save(array $manifest,string $endpoint,int $userId):array{$module=$manifest['module'];$instance=$manifest['connection']['module_instance_id'];$existingProject=$this->projectByCode($module['product']);$existingInstance=$this->connectionByInstance($instance);if($existingProject){$current=$this->connectionForProject((int)$existingProject['id']);if($current&&$current['module_instance_id']!==$instance)throw new ModuleAttachmentException('product_conflict','Existe outro módulo utilizando este identificador.');if($existingInstance&&(int)$existingInstance['project_id']!==(int)$existingProject['id'])throw new ModuleAttachmentException('instance_conflict','Este módulo já está anexado.');$projectId=(int)$existingProject['id'];$this->db->prepare('UPDATE projects SET name=?,full_name=?,description=?,icon=?,version=?,url=?,admin_url=?,category=?,status=? WHERE id=?')->execute([$module['name'],$module['full_name'],$module['description'],$module['icon'],$module['version'],$module['public_url'],$module['admin_url'],$module['category'],$module['status'],$projectId]);}else{if($existingInstance)throw new ModuleAttachmentException('instance_conflict','Este módulo já está anexado.');$s=$this->db->prepare('INSERT INTO projects(name,full_name,code,description,icon,version,url,admin_url,category,status,display_order) VALUES(?,?,?,?,?,?,?,?,?,?,999)');$s->execute([$module['name'],$module['full_name'],$module['product'],$module['description'],$module['icon'],$module['version'],$module['public_url'],$module['admin_url'],$module['category'],$module['status']]);$projectId=(int)$this->db->lastInsertId();}$capabilities=json_encode($manifest['capabilities'],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$attached=date('Y-m-d H:i:s',strtotime($manifest['connection']['attached_at']));$now=date('Y-m-d H:i:s');if($existingInstance){$this->db->prepare("UPDATE project_connections SET endpoint_url=?,connection_status='attached',capabilities_json=?,public_key_fingerprint=?,last_verified_at=?,last_error_code=NULL,updated_at=? WHERE id=?")->execute([$endpoint,$capabilities,$manifest['public_key_fingerprint'],$now,$now,$existingInstance['id']]);$action='project.connection_updated';}else{$this->db->prepare("INSERT INTO project_connections(project_id,module_instance_id,protocol_version,endpoint_url,connection_status,capabilities_json,public_key_fingerprint,attached_by_user_id,attached_at,last_verified_at) VALUES(?,?,1,?,'attached',?,?,?,?,?)")->execute([$projectId,$instance,$endpoint,$capabilities,$manifest['public_key_fingerprint'],$userId,$attached,$now]);$action='project.attached';}return ['project_id'=>$projectId,'action'=>$action,'created'=>$existingProject===null];} }
